      "code": "// ==========================================\n// Arduino Uno R3: ไฟกะพริบ + สวิตช์ปุ่มกด + Serial Monitor\n// เพียงเปลี่ยนหมายเลขขาด้านล่างก็ใช้งานได้ทันที\n// ==========================================\n#define LED_PIN    13    // ขาควบคุม LED (มี LED ในตัวที่ขา 13)\n#define BUTTON_PIN 2     // ขาต่อสวิตช์ปุ่มกด (ต่อขาหนึ่งเข้า D2 อีกขาลง GND)\n\nvoid setup() {\n  pinMode(LED_PIN, OUTPUT);          // ตั้งขา LED เป็น Output\n  pinMode(BUTTON_PIN, INPUT_PULLUP); // ใช้งาน Pull-up ภายในบอร์ด\n  Serial.begin(9600);                // เปิด Serial Monitor ที่ความเร็ว 9600 baud\n  Serial.println(\"Arduino Uno R3 is ready!\");\n}\n\nvoid loop() {\n  int buttonState = digitalRead(BUTTON_PIN);\n  \n  if (buttonState == LOW) { // เมื่อกดปุ่ม (สัญญานต่อลง GND)\n    digitalWrite(LED_PIN, HIGH); // เปิดไฟ LED\n    Serial.println(\"Button Pressed -> LED ON\");\n  } else {\n    digitalWrite(LED_PIN, LOW);  // ปิดไฟ LED\n  }\n  delay(100); // หน่วงเวลาเล็กน้อยเพื่อเสถียรภาพ\n}"
