      "code": "// ==========================================\n// Arduino Nano: อ่านค่าเซ็นเซอร์ Analog (A0) และปรับไฟหรี่ PWM (D9)\n// เปลี่ยนหมายเลขขาด้านล่างตามวงจรของคุณได้ทันที\n// ==========================================\n#define ANALOG_PIN   A0  // ขารับค่า Analog (0-1023) เช่น LDR หรือ Potentiometer\n#define PWM_LED_PIN  9   // ขาขับหลอด LED แบบ PWM (D3, D5, D6, D9, D10, D11)\n\nvoid setup() {\n  pinMode(PWM_LED_PIN, OUTPUT);\n  Serial.begin(9600);\n  Serial.println(\"Arduino Nano Analog & PWM Demo\");\n}\n\nvoid loop() {\n  int sensorVal = analogRead(ANALOG_PIN);          // อ่านค่า 0 - 1023\n  int brightness = map(sensorVal, 0, 1023, 0, 255); // ปรับสเกลเป็น 0 - 255 สำหรับ PWM\n  \n  analogWrite(PWM_LED_PIN, brightness);           // ปรับความสว่างของ LED\n  \n  Serial.print(\"Sensor: \");\n  Serial.print(sensorVal);\n  Serial.print(\" | Brightness: \");\n  Serial.println(brightness);\n  \n  delay(100); // อัปเดตทุก 0.1 วินาที\n}"
