      "code": "// ==========================================\n// ESP8266 NodeMCU: เชื่อมต่อ Wi-Fi และเปิด-ปิดขา D1\n// แก้ไขชื่อ Wi-Fi, รหัสผ่าน และเลขขา OUTPUT_PIN ด้านล่างได้ทันที\n// ==========================================\n#include <ESP8266WiFi.h>\n\n#define OUTPUT_PIN  D1   // ขาควบคุมโหลดหรือรีเลย์ (เช่น ขา D1 หรือ D2)\n#define ONBOARD_LED D4   // LED บนบอร์ด NodeMCU (Active LOW: LOW=ติด, HIGH=ดับ)\n\nconst char* ssid     = \"YOUR_WIFI_NAME\";     // ใส่ชื่อ Wi-Fi ของคุณ\nconst char* password = \"YOUR_WIFI_PASSWORD\"; // ใส่รหัสผ่าน Wi-Fi ของคุณ\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(OUTPUT_PIN, OUTPUT);\n  pinMode(ONBOARD_LED, OUTPUT);\n  digitalWrite(OUTPUT_PIN, LOW);\n  digitalWrite(ONBOARD_LED, HIGH); // ปิด LED ก่อน\n\n  Serial.println(\"\\n--- NodeMCU Wi-Fi Initializing ---\");\n  Serial.print(\"Connecting to: \");\n  Serial.println(ssid);\n\n  WiFi.mode(WIFI_STA);\n  WiFi.begin(ssid, password);\n\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(400);\n    Serial.print(\".\");\n    digitalWrite(ONBOARD_LED, !digitalRead(ONBOARD_LED)); // กะพริบไฟขณะรอต่อ\n  }\n\n  digitalWrite(ONBOARD_LED, LOW); // ติดค้างเมื่อต่อ Wi-Fi สำเร็จ\n  Serial.println(\"\\n>>> NodeMCU Connected! <<<\");\n  Serial.print(\"IP Address: \");\n  Serial.println(WiFi.localIP());\n}\n\nvoid loop() {\n  // กะพริบทดสอบขา OUTPUT_PIN ทุกๆ 2 วินาที\n  digitalWrite(OUTPUT_PIN, HIGH);\n  delay(2000);\n  digitalWrite(OUTPUT_PIN, LOW);\n  delay(2000);\n}"
