      "code": "// ==========================================\n// HC-SR04 Ultrasonic: เซ็นเซอร์วัดระยะทาง\n// เปลี่ยนหมายเลขขา TRIG_PIN และ ECHO_PIN ด้านล่างได้ทันที\n// ==========================================\n#define TRIG_PIN 9    // ขาส่งคำสั่งยิงคลื่นเสียง (Digital Output)\n#define ECHO_PIN 10   // ขารับสัญญาณคลื่นสะท้อน (Digital Input)\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(TRIG_PIN, OUTPUT);\n  pinMode(ECHO_PIN, INPUT);\n  Serial.println(\"HC-SR04 Ultrasonic Sensor Ready!\");\n}\n\nvoid loop() {\n  // เคลียร์สัญญาณขา Trig ให้เป็น LOW ชั่วครู่\n  digitalWrite(TRIG_PIN, LOW);\n  delayMicroseconds(2);\n\n  // ส่งสัญญาณพัลส์ HIGH นาน 10 ไมโครวินาที เพื่อสั่งยิงคลื่นเสียง\n  digitalWrite(TRIG_PIN, HIGH);\n  delayMicroseconds(10);\n  digitalWrite(TRIG_PIN, LOW);\n\n  // จับเวลาที่ขา Echo เป็น HIGH (หน่วยเป็นไมโครวินาที) Timeout ที่ 30,000µs (~5 เมตร)\n  long duration = pulseIn(ECHO_PIN, HIGH, 30000);\n\n  if (duration == 0) {\n    Serial.println(\"อยู่นอกระยะตรวจจับ (เกิน 400 cm หรือไม่มีวัตถุ)\");\n  } else {\n    // ความเร็วเสียงในอากาศประมาณ 0.0343 ซม./ไมโครวินาที (หาร 2 เพราะไป-กลับ)\n    float distanceCm = (duration * 0.0343) / 2.0;\n    \n    Serial.print(\"ระยะทาง: \");\n    Serial.print(distanceCm, 1);\n    Serial.println(\" cm\");\n  }\n\n  delay(150); // รอ 150ms ก่อนวัดรอบถัดไป\n}"
