      "code": "// ==========================================\n// SG90 Micro Servo: ควบคุมการหมุนกวาดมุม 0 - 180 องศา\n// เปลี่ยนหมายเลขขา SERVO_PIN ด้านล่างได้ทันที\n// ==========================================\n#include <Servo.h>\n\n#define SERVO_PIN 9   // กำหนดขา PWM ที่ต่อกับสายสัญญาณสีส้มของเซอร์โว (เช่น ขา 9)\n\nServo myServo;        // สร้างอ็อบเจกต์สำหรับสั่งการเซอร์โว\n\nvoid setup() {\n  Serial.begin(9600);\n  myServo.attach(SERVO_PIN); // เชื่อมต่อขาควบคุมเข้ากับเซอร์โว\n  Serial.println(\"SG90 Servo Initialized! Starting 0 - 180 degree sweep...\");\n}\n\nvoid loop() {\n  // หมุนจาก 0 ไปยัง 180 องศา ทีละ 1 องศา\n  Serial.println(\"Moving: 0 -> 180 deg\");\n  for (int angle = 0; angle <= 180; angle += 1) {\n    myServo.write(angle); // สั่งให้เซอร์โวหมุนไปยังมุมที่กำหนด\n    delay(15);            // หน่วงเวลา 15ms เพื่อให้การเคลื่อนที่นุ่มนวล\n  }\n  delay(500); // พักครึ่งวินาทีที่มุม 180 องศา\n\n  // หมุนกลับจาก 180 ไปยัง 0 องศา\n  Serial.println(\"Moving: 180 -> 0 deg\");\n  for (int angle = 180; angle >= 0; angle -= 1) {\n    myServo.write(angle);\n    delay(15);\n  }\n  delay(500); // พักครึ่งวินาทีที่มุม 0 องศา\n}"
